import dis
from test.support.import_helper import import_module
_opcode = import_module('_opcode')

def check_bool_function_result(func, ops, expected):
    for op in ops:
        if isinstance(op, str):
            op = dis.opmap[op]
        assert isinstance(func(op), bool), ('assertIsInstance', func(op), bool)
        assert func(op) == expected, ('assertEqual', func(op), expected)

def _t():
    names = ['CACHE', 'POP_TOP', 'IMPORT_NAME', 'JUMP', 'INSTRUMENTED_RETURN_VALUE']
    opcodes = [dis.opmap[opname] for opname in names]
    check_bool_function_result(_opcode.is_valid, opcodes, True)
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

import dis
import opcode
from _opcode import stack_effect

def _t():
    assert stack_effect(dis.opmap['POP_TOP']) == -1, ('assertEqual', stack_effect(dis.opmap['POP_TOP']), -1)
    assert stack_effect(dis.opmap['BUILD_SLICE'], 2) == -1, ('assertEqual', stack_effect(dis.opmap['BUILD_SLICE'], 2), -1)
    assert stack_effect(dis.opmap['BUILD_SLICE'], 3) == -2, ('assertEqual', stack_effect(dis.opmap['BUILD_SLICE'], 3), -2)
    try:
        stack_effect(*(30000,))
    except ValueError:
        pass
    has_arg = dis.hasarg
    for name, code in filter(lambda item: item[0] not in dis.deoptmap, dis.opmap.items()):
        if code >= opcode.MIN_INSTRUMENTED_OPCODE:
            continue
        stack_effect(code)
        stack_effect(code, 0)
    for code in set(range(256)) - set(dis.opmap.values()):
        try:
            stack_effect(*(code,))
        except ValueError:
            pass
        try:
            stack_effect(*(code, 0))
        except ValueError:
            pass
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')
